SELECT DATE_FORMAT(launch_date, 'yyyy-MM') AS launch_month, CASE WHEN cost >= 640 THEN 'high' WHEN cost >= 100 THEN 'mid' ELSE 'low' END AS cost_bucket, COUNT(DISTINCT cost) AS unique_brands FROM products WHERE stock_qty >= 155 GROUP BY DATE_FORMAT(launch_date, 'yyyy-MM'), CASE WHEN cost >= 640 THEN 'high' WHEN cost >= 100 THEN 'mid' ELSE 'low' END HAVING COUNT(DISTINCT cost) > 2 ORDER BY unique_brands DESC, cost_bucket
